+  border:1px solid var(--line);
+  box-shadow:var(--shadow);
+  outline:none;
+}
+
+/* Top promo */
+.topbar{
+  position:sticky;
+  top:0;
+  z-index:50;
+  background:linear-gradient(90deg, rgba(230,57,70,.24), rgba(0,0,0,.65));
+  border-bottom:1px solid rgba(230,57,70,.25);
+  backdrop-filter: blur(10px);
+}
+.topbar-inner{
+  display:flex;
+  align-items:center;
+  justify-content:space-between;
+  gap:14px;
+  padding:10px 0;
+}
+.topbar-text{
+  font-weight:700;
+  letter-spacing:.02em;
+  color:rgba(255,255,255,.92);
+}
+.topbar a.btn{padding:10px 14px}
+
+/* Header / nav */
+header.site-header{
+  position:sticky;
+  top:46px;
+  z-index:40;
+  background:rgba(17,17,17,.70);
+  border-bottom:1px solid var(--line);
+  backdrop-filter: blur(10px);
+}
+.nav{
+  display:flex;
+  align-items:center;
+  justify-content:space-between;
+  gap:16px;
+  padding:14px 0;
+}
+.brand{
+  display:flex;
+  align-items:center;
+  gap:10px;
+  min-width:200px;
+}
+.logo{
+  width:36px; height:36px;
+  border-radius:12px;
+  background:conic-gradient(from 180deg, var(--red-2), #ff6b77, var(--red-2));
+  box-shadow:0 0 0 1px rgba(255,255,255,.10), 0 12px 30px rgba(230,57,70,.20);
+}
+.brand span{
+  font-family:Oswald, Impact, Haettenschweiler, 'Arial Narrow Bold', sans-serif;
+  letter-spacing:.08em;
+  text-transform:uppercase;
+  font-size:18px;
+}
+
+.nav-links{display:flex; align-items:center; gap:18px; flex-wrap:wrap}
+.nav-links a{
+  font-weight:650;
+  color:rgba(255,255,255,.86);
+  letter-spacing:.02em;
+  padding:10px 10px;
+  border-radius:12px;
+}
+.nav-links a[aria-current="page"],
+.nav-links a:hover{
+  background:rgba(255,255,255,.06);
+  color:rgba(255,255,255,.98);
+}
+
+.nav-cta{display:flex; align-items:center; gap:10px}
+
+.btn{
+  display:inline-flex;
+  align-items:center;
+  justify-content:center;
+  gap:10px;
+  border:1px solid var(--line);
+  padding:12px 16px;
+  border-radius:999px;
+  background:rgba(255,255,255,.05);
+  color:rgba(255,255,255,.92);
+  font-weight:750;
+  letter-spacing:.02em;
+  cursor:pointer;
+  user-select:none;
+}
+.btn:hover{background:rgba(255,255,255,.08)}
+.btn:focus-visible{outline:none; box-shadow:var(--focus)}
+.btn-primary{
+  background:linear-gradient(135deg, var(--red-2), var(--red));
+  border-color:rgba(230,57,70,.55);
+  box-shadow:0 18px 42px rgba(230,57,70,.22);
+}
+.btn-primary:hover{filter:saturate(1.05) brightness(1.02)}
+.btn-ghost{background:transparent}
+.btn-small{padding:10px 12px; font-weight:700}
+
+.mobile-toggle{display:none}
+
+main{padding-bottom:60px}
+
+/* Hero */
+.hero{
+  padding:56px 0 26px;
+}
+.hero-grid{
+  display:grid;
+  grid-template-columns: 1.15fr .85fr;
+  gap:26px;
+  align-items:stretch;
+}
+.hero-card{
+  border:1px solid var(--line);
+  border-radius:var(--radius);
+  background:linear-gradient(180deg, rgba(255,255,255,.06), rgba(255,255,255,.02));
+  box-shadow:var(--shadow);
+  overflow:hidden;
+}
+
+.kicker{
+  font-family:Oswald, Impact, sans-serif;
+  letter-spacing:.22em;
+  text-transform:uppercase;
+  color:rgba(255,255,255,.72);
+  font-size:12px;
+}
+
+h1,h2,h3{
+  font-family:Oswald, Impact, sans-serif;
+  letter-spacing:.04em;
+  text-transform:uppercase;
+  margin:10px 0 10px;
+  line-height:1.05;
+}
+h1{font-size: clamp(40px, 5vw, 64px)}
+h2{font-size: clamp(28px, 3.1vw, 40px)}
+h3{font-size: clamp(18px, 2vw, 24px)}
+
+.lead{color:rgba(255,255,255,.82); font-size:16px; max-width:62ch}
+.hero-body{padding:28px}
+.hero-actions{display:flex; gap:12px; flex-wrap:wrap; margin-top:18px}
+
+/* Carousel */
+.carousel{
+  position:relative;
+  height:100%;
+  min-height:360px;
+}
+.carousel-track{
+  display:flex;
+  width:100%;
+  height:100%;
+  transition:transform 500ms cubic-bezier(.2,.8,.2,1);
+}
+.slide{
+  min-width:100%;
+  height:100%;
+  background-size:cover;
+  background-position:center;
+  position:relative;
+}
+.slide::after{
+  content:"";
+  position:absolute; inset:0;
+  background:linear-gradient(0deg, rgba(0,0,0,.70), rgba(0,0,0,.20) 55%, rgba(230,57,70,.16));
+}
+.carousel-ui{
+  position:absolute;
+  inset:0;
+  display:flex;
+  align-items:stretch;
+  justify-content:space-between;
+  pointer-events:none;
+}
+.carousel-arrow{
+  pointer-events:auto;
+  align-self:center;
+  margin:0 14px;
+  width:44px; height:44px;
+  border-radius:999px;
+  border:1px solid rgba(255,255,255,.18);
+  background:rgba(0,0,0,.45);
+  color:rgba(255,255,255,.92);
+  display:grid;
+  place-items:center;
+  cursor:pointer;
+}
+.carousel-arrow:hover{background:rgba(0,0,0,.60)}
+.carousel-arrow:focus-visible{outline:none; box-shadow:var(--focus)}
+.carousel-meta{
+  position:absolute;
+  left:18px;
+  bottom:16px;
+  display:flex;
+  align-items:center;
+  gap:10px;
+  padding:10px 12px;
+  border-radius:999px;
+  background:rgba(0,0,0,.35);
+  border:1px solid rgba(255,255,255,.12);
+  backdrop-filter: blur(10px);
+}
+.dots{display:flex; gap:6px}
+.dot{
+  width:7px; height:7px;
+  border-radius:999px;
+  background:rgba(255,255,255,.35);
+}
+.dot.active{background:var(--red)}
+.carousel-label{font-weight:700; color:rgba(255,255,255,.82); font-size:12px; letter-spacing:.06em; text-transform:uppercase}
+
+/* Sections */
+section{padding:44px 0}
+.section-head{display:flex; align-items:flex-end; justify-content:space-between; gap:16px; margin-bottom:18px}
+.section-sub{color:var(--muted); max-width:68ch}
+
+.grid-2{display:grid; grid-template-columns: 1fr 1fr; gap:18px}
+.card{
+  border:1px solid var(--line);
+  border-radius:var(--radius);
+  background:linear-gradient(180deg, rgba(255,255,255,.05), rgba(255,255,255,.02));
+  box-shadow:var(--shadow);
+}
+.card.pad{padding:22px}
+.pill{
+  display:inline-flex;
+  align-items:center;
+  gap:8px;
+  padding:8px 12px;
+  border-radius:999px;
+  background:rgba(230,57,70,.12);
+  border:1px solid rgba(230,57,70,.30);
+  color:rgba(255,255,255,.86);
+  font-weight:800;
+  letter-spacing:.08em;
+  text-transform:uppercase;
+  font-size:11px;
+}
+
+.feature-list{display:grid; grid-template-columns: repeat(3, 1fr); gap:14px}
+.feature{
+  padding:18px;
+  border-radius:var(--radius-sm);
+  border:1px solid var(--line);
+  background:linear-gradient(180deg, rgba(0,0,0,.35), rgba(0,0,0,.15));
+}
+.feature p{margin:8px 0 0; color:rgba(255,255,255,.78)}
+
+/* Dominant CTA */
+.cta-dominant{
+  border-radius: calc(var(--radius) + 6px);
+  border:1px solid rgba(230,57,70,.35);
+  background:
+    radial-gradient(650px 260px at 20% 10%, rgba(230,57,70,.28), transparent 60%),
+    radial-gradient(650px 260px at 70% 80%, rgba(230,57,70,.22), transparent 60%),
+    linear-gradient(180deg, rgba(255,255,255,.06), rgba(0,0,0,.40));
+  box-shadow:0 22px 65px rgba(230,57,70,.12), var(--shadow);
+  padding:26px;
+  display:flex;
+  flex-wrap:wrap;
+  justify-content:space-between;
+  align-items:center;
+  gap:16px;
+}
+.cta-dominant h2{margin:0}
+.cta-dominant .cta-copy{max-width:62ch}
+
+/* Toggle */
+.toggle{
+  display:inline-flex;
+  border:1px solid var(--line);
+  background:rgba(255,255,255,.04);
+  border-radius:999px;
+  padding:6px;
+  gap:6px;
+}
+.toggle button{
+  border:0;
+  background:transparent;
+  color:rgba(255,255,255,.80);
+  font-weight:800;
+  letter-spacing:.06em;
+  text-transform:uppercase;
+  padding:10px 14px;
+  border-radius:999px;
+  cursor:pointer;
+}
+.toggle button[aria-pressed="true"]{
+  background:linear-gradient(135deg, rgba(230,57,70,.95), rgba(255,15,36,.92));
+  color:white;
+}
+.toggle button:focus-visible{outline:none; box-shadow:var(--focus)}
+
+.fade-swap{position:relative}
+.fade-swap[data-state="exiting"]{opacity:0; transform: translateY(6px)}
+.fade-swap{transition:opacity 220ms ease, transform 220ms ease}
+
+/* Table */
+table{
+  width:100%;
+  border-collapse:separate;
+  border-spacing:0;
+  overflow:hidden;
+  border-radius:var(--radius);
+  border:1px solid var(--line);
+  background:rgba(0,0,0,.20);
+}
+th,td{padding:14px 14px; text-align:left}
+th{
+  background:rgba(255,255,255,.06);
+  border-bottom:1px solid var(--line);
+  font-family:Oswald, Impact, sans-serif;
+  text-transform:uppercase;
+  letter-spacing:.08em;
+  font-size:13px;
+}
+tr + tr td{border-top:1px solid rgba(255,255,255,.06)}
+td{color:rgba(255,255,255,.86)}
+
+/* Instructors */
+.filters{display:flex; align-items:center; gap:12px; flex-wrap:wrap}
+select{
+  background:rgba(255,255,255,.05);
+  color:rgba(255,255,255,.92);
+  border:1px solid var(--line);
+  border-radius:14px;
+  padding:12px 12px;
+  min-width:220px;
+}
+select:focus-visible{outline:none; box-shadow:var(--focus)}
+
+.grid-cards{display:grid; grid-template-columns: repeat(4, 1fr); gap:14px}
+.person{
+  border:1px solid var(--line);
+  border-radius:var(--radius);
+  overflow:hidden;
+  background:linear-gradient(180deg, rgba(255,255,255,.05), rgba(255,255,255,.02));
+}
+.avatar{
+  height:132px;
+  background:
+    radial-gradient(900px 200px at 10% 10%, rgba(230,57,70,.34), transparent 60%),
+    radial-gradient(700px 180px at 90% 30%, rgba(255,15,36,.18), transparent 60%),
+    linear-gradient(135deg, rgba(0,0,0,.65), rgba(0,0,0,.25));
+}
+.person-body{padding:14px}
+.person-name{font-weight:900; letter-spacing:.02em}
+.person-meta{color:rgba(255,255,255,.72); font-size:13px; margin-top:2px}
+.person-actions{margin-top:12px; display:flex; gap:10px; flex-wrap:wrap}
+.person[hidden]{display:none}
+
+/* FAQ */
+.accordion{display:grid; gap:10px}
+.acc-item{
+  border:1px solid var(--line);
+  border-radius:var(--radius);
+  background:rgba(255,255,255,.03);
+  overflow:hidden;
+}
+.acc-button{
+  width:100%;
+  display:flex;
+  justify-content:space-between;
+  align-items:center;
+  gap:14px;
+  padding:16px 16px;
+  border:0;
+  background:transparent;
+  color:rgba(255,255,255,.92);
+  cursor:pointer;
+  font-weight:850;
+  letter-spacing:.02em;
+  text-align:left;
+}
+.acc-button:focus-visible{outline:none; box-shadow:var(--focus)}
+.acc-icon{width:18px; height:18px; flex:0 0 auto; border-radius:5px; border:1px solid rgba(255,255,255,.18); display:grid; place-items:center}
+.acc-panel{max-height:0; overflow:hidden; transition:max-height 260ms ease}
+.acc-panel-inner{padding:0 16px 16px; color:rgba(255,255,255,.78)}
+.acc-item[data-open="true"] .acc-panel{max-height:320px}
+.acc-item[data-open="true"] .acc-icon{border-color:rgba(230,57,70,.45); box-shadow:0 0 0 3px rgba(230,57,70,.20) inset}
+
+/* Newsletter */
+.form-row{display:flex; gap:12px; flex-wrap:wrap; align-items:flex-start}
+.input{
+  flex:1 1 260px;
+  padding:12px 14px;
+  border-radius:14px;
+  border:1px solid var(--line);
+  background:rgba(255,255,255,.04);
+  color:rgba(255,255,255,.92);
+}
+.input:focus-visible{outline:none; box-shadow:var(--focus)}
+.field{display:grid; gap:8px}
+.help{font-size:13px; color:rgba(255,255,255,.68)}
+.help.error{color:#ff8b94}
+.help.ok{color:#9bffbf}
+
+/* Footer */
+footer{
+  border-top:1px solid var(--line);
+  background:rgba(0,0,0,.30);
+}
+.footer-grid{
+  display:grid;
+  grid-template-columns: 1.25fr 1fr 1fr 1fr;
+  gap:16px;
+  padding:34px 0;
+}
+.footer-col h3{margin:0 0 12px; font-size:18px}
+.footer-col a{display:block; padding:8px 0; color:rgba(255,255,255,.72)}
+.footer-col a:hover{color:rgba(255,255,255,.95)}
+.footer-bottom{padding:14px 0 28px; display:flex; align-items:center; justify-content:space-between; gap:10px; flex-wrap:wrap; color:rgba(255,255,255,.60)}
+
+/* Country selector */
+.country-wrap{position:relative}
+.country-menu{
+  position:absolute;
+  right:0;
+  bottom:48px;
+  min-width:220px;
+  border-radius:16px;
+  border:1px solid var(--line);
+  background:rgba(0,0,0,.70);
+  backdrop-filter: blur(12px);
+  box-shadow:var(--shadow);
+  padding:10px;
+  display:none;
+}
+.country-menu[data-open="true"]{display:block}
+.country-menu button{
+  width:100%;
+  display:flex;
+  justify-content:space-between;
+  gap:10px;
+  padding:10px 10px;
+  background:transparent;
+  border:0;
+  border-radius:12px;
+  color:rgba(255,255,255,.86);
+  cursor:pointer;
+  text-align:left;
+}
+.country-menu button:hover{background:rgba(255,255,255,.06)}
+
+/* Responsive */
+@media (max-width: 980px){
+  .hero-grid{grid-template-columns: 1fr}
+  .carousel{min-height:320px}
+  .feature-list{grid-template-columns: 1fr}
+  .grid-cards{grid-template-columns: repeat(2, 1fr)}
+  .footer-grid{grid-template-columns: 1fr 1fr}
+  header.site-header{top:44px}
+}
+
+@media (max-width: 720px){
+  .nav{align-items:flex-start}
+  .nav-links{display:none; width:100%; padding-top:8px}
+  .nav-links[data-open="true"]{display:flex}
+  .nav-cta{width:100%; justify-content:flex-start; flex-wrap:wrap}
+  .mobile-toggle{display:inline-flex}
+  header.site-header{top:44px}
+  .footer-grid{grid-template-columns: 1fr}
+  .grid-2{grid-template-columns: 1fr}
+  .grid-cards{grid-template-columns: 1fr}
+}
+
+@media (prefers-reduced-motion: reduce){
+  .carousel-track,.fade-swap,.acc-panel{transition:none}
+}
*** End Patch
PATCH

